import 'package:flutter/material.dart'; import 'package:provider/provider.dart'; import '../services/recipe_store.dart';
class AddRecipeScreen extends StatefulWidget { const AddRecipeScreen({super.key}); @override State<AddRecipeScreen> createState()=>_AddRecipeScreenState(); }
class _AddRecipeScreenState extends State<AddRecipeScreen>{ final _form=GlobalKey<FormState>(); final _name=TextEditingController(),_origin=TextEditingController(),_ingredients=TextEditingController(),_method=TextEditingController(),_prep=TextEditingController(text:'10'),_cook=TextEditingController(text:'20'); String _diet='Vegetarian',_category='Main Course',_difficulty='Easy'; bool _saving=false;
 @override void dispose(){for(final c in [_name,_origin,_ingredients,_method,_prep,_cook]){c.dispose();}super.dispose();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Add a recipe')),body:Form(key:_form,child:ListView(padding:const EdgeInsets.all(18),children:[Text('Your recipe, your way',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:6),const Text('Recipes are saved privately on this device.'),const SizedBox(height:18),_field(_name,'Recipe name',required:true),_field(_origin,'Origin or region'),Row(children:[Expanded(child:DropdownButtonFormField(initialValue:_diet,decoration:const InputDecoration(labelText:'Diet'),items:['Vegetarian','Non-vegetarian','Vegan','Eggetarian'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>_diet=v!))),const SizedBox(width:12),Expanded(child:DropdownButtonFormField(initialValue:_category,decoration:const InputDecoration(labelText:'Category'),items:['Breakfast','Snack','Main Course','Dessert','Drink'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>_category=v!)))]),const SizedBox(height:12),_field(_ingredients,'Ingredients (one per line)',required:true,lines:5),_field(_method,'Preparation steps (one per line)',required:true,lines:5),Row(children:[Expanded(child:_field(_prep,'Prep min',number:true)),const SizedBox(width:12),Expanded(child:_field(_cook,'Cook min',number:true))]),DropdownButtonFormField(initialValue:_difficulty,decoration:const InputDecoration(labelText:'Difficulty'),items:['Easy','Medium','Hard'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>_difficulty=v!)),const SizedBox(height:20),FilledButton.icon(onPressed:_saving?_noop:_save,icon:_saving?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.save_outlined),label:const Text('Save recipe'))])));
 void _noop(){} Widget _field(TextEditingController c,String label,{bool required=false,bool number=false,int lines=1})=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextFormField(controller:c,maxLines:lines,keyboardType:number?TextInputType.number:TextInputType.multiline,decoration:InputDecoration(labelText:label,alignLabelWithHint:lines>1),validator:(v){if(required&&(v==null||v.trim().isEmpty))return 'Please enter ${label.toLowerCase()}.';if(number&&(v==null||int.tryParse(v.trim())==null||int.parse(v.trim())<0))return 'Enter a valid number.';return null; }));
 Future<void> _save()async{if(!_form.currentState!.validate())return;setState(()=>_saving=true);try{await context.read<RecipeStore>().addRecipe(name:_name.text,origin:_origin.text,diet:_diet,category:_category,ingredients:_lines(_ingredients.text),method:_method.text,prepMinutes:int.parse(_prep.text),cookMinutes:int.parse(_cook.text),difficulty:_difficulty,steps:_lines(_method.text));if(mounted)Navigator.pop(context,true);}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Could not save recipe. Please try again.')));}finally{if(mounted)setState(()=>_saving=false);}}
 List<String> _lines(String s)=>s.split('\n').map((x)=>x.trim()).where((x)=>x.isNotEmpty).toList();
}
